+  const actual = await importOriginal<typeof import("@/services/workflow-backend")>();
+  return {
+    ...actual,
+    getWorkspace: vi.fn(),
+    searchWorkspaceTasks: vi.fn(),
+    searchWorkspaceTasksPage: vi.fn(),
+    searchFeaturesPage: vi.fn(),
+  };
+});
+
