+        taskId: "task-1",
+        taskName: "T1",
+        title: "Task 1",
+        parentFeatureTabSessionId: "feat-xyz",
+      },
+      {
+        sessionId: "task-def",
+        workspaceId: "ws-1",
+        taskId: "task-2",
+        taskName: "T2",
+        title: "Task 2",
+      },
+    ];
