+    const tabs: TaskTabEntry[] = [
+      {
+        sessionId: "task-abc",
+        workspaceId: "ws-1",
+        taskId: "task-1",
+        taskName: "T1",
+        title: "Task 1",
+        parentFeatureTabSessionId: "feat-xyz",
